1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's numeric membership level (1 to 3) on creation: it starts at
7	 * 1, gains 1 when an email is present, gains 1 when {@code namesakeCount} is 0,
8	 * and is capped at 3 (level 4 is reserved for tenure).
9	 */
10	public final class MembershipLevel {
11	
12	    private MembershipLevel() {
13	    }
14	
15	    /** Membership level (1 to 3) derived from the owner's email and namesake count. */
16	    public static int of(Owner owner) {
17	        int level = 1;
18	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
19	            level += 1;
20	        }
21	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
22	            level += 1;
23	        }
24	        return Math.min(level, 3);
25	    }
26	}
