1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Records how many existing owners (before this create) share the new owner's firstName and
11	 * lastName, compared case-insensitively. Runs after {@link BuildOwner} and before the owner is
12	 * saved, so the count reflects only pre-existing owners. Stamps the value on the owner via
13	 * {@link Owner#setNamesakeCount(Integer)}; it is returned as {@code namesakeCount}.
14	 */
15	public class CountOwnerNamesakes {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String firstName = key(owner.getFirstName());
19	        String lastName = key(owner.getLastName());
20	        int count = 0;
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
23	                continue; // the owner being created is not its own namesake
24	            }
25	            if (firstName.equals(key(existing.getFirstName()))
26	                    && lastName.equals(key(existing.getLastName()))) {
27	                count++;
28	            }
29	        }
30	        owner.setNamesakeCount(count);
31	    }
32	
33	    private static String key(String value) {
34	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
35	    }
36	}
